+package htmlelements
+{
+	/**
+	 * Utility helpers for safely handling values that are passed from the
+	 * HTML page into the SWF (FlashVars) and later injected back into a
+	 * JavaScript context through ExternalInterface.call().
+	 *
+	 * Because the callback / init function names and element ids are emitted
+	 * verbatim into a JavaScript expression, they MUST be restricted to a
+	 * safe set of characters that can only form a legitimate JavaScript
+	 * identifier / member-access expression. Otherwise an attacker can
+	 * inject arbitrary script (CWE-79, CVE-2016-4567), e.g. by using an
+	 * obfuscated parameter such as "jsinitfunctio%gn".
+	 */
+	public class JsUtil
+	{
+		// Matches a chain of valid JS identifiers separated by dots,
+		// e.g. "myObject.onFlashReady" or "mejs_callback".
+		private static const VALID_NAME:RegExp =
+			/^[A-Za-z_$][A-Za-z0-9_$]*(\.[A-Za-z_$][A-Za-z0-9_$]*)*$/;
+
+		/**
+		 * Returns the supplied name only if it is a valid JavaScript
+		 * identifier / dotted member expression; otherwise returns an
+		 * empty string so that no untrusted content is ever passed to
+		 * ExternalInterface.call().
+		 */
+		public static function sanitizeCallbackName(name:String):String
+		{
+			if (name == null) {
+				return "";
+			}
+
+			// Decode any percent-encoding first, so that obfuscated
+			// values (e.g. "jsinitfunctio%gn") cannot slip through.
+			var decoded:String;
+			try {
+				decoded = unescape(name);
+			} catch (e:Error) {
+				return "";
+			}
+
+			if (VALID_NAME.test(decoded)) {
+				return decoded;
+			}
+
+			return "";
+		}
+	}
+}

