+package org.apache.streampipes.storage.management.util;
+
+import org.slf4j.Logger;
+import org.slf4j.LoggerFactory;
+
+import java.net.InetAddress;
+import java.net.URI;
+import java.net.URISyntaxException;
+import java.net.UnknownHostException;
+
+/**
+ * Validates endpoint URLs that are used to install additional pipeline elements
+ * in order to mitigate Server-Side Request Forgery (SSRF) attacks (CWE-918).
+ */
+public class EndpointUrlValidator {
+
+  private static final Logger LOG = LoggerFactory.getLogger(EndpointUrlValidator.class);
+
+  private EndpointUrlValidator() {
+    // utility class
+  }
+
+  /**
+   * Checks whether the provided endpoint URL is safe to be queried by StreamPipes.
+   * Only http/https schemes are allowed and the resolved host must not point to
+   * a loopback, link-local, site-local, multicast or otherwise non-public address.
+   *
+   * @param endpointUrl the endpoint URL to validate
+   * @return {@code true} if the URL is considered safe, {@code false} otherwise
+   */
+  public static boolean isValidEndpoint(String endpointUrl) {
+    if (endpointUrl == null || endpointUrl.trim().isEmpty()) {
+      return false;
+    }
+
+    final URI uri;
+    try {
+      uri = new URI(endpointUrl.trim());
+    } catch (URISyntaxException e) {
+      LOG.warn("Rejected endpoint URL '{}' due to invalid syntax", endpointUrl);
+      return false;
+    }
+
+    final String scheme = uri.getScheme();
+    if (scheme == null
+        || !(scheme.equalsIgnoreCase("http") || scheme.equalsIgnoreCase("https"))) {
+      LOG.warn("Rejected endpoint URL '{}' because of disallowed scheme", endpointUrl);
+      return false;
+    }
+
+    final String host = uri.getHost();
+    if (host == null || host.isEmpty()) {
+      LOG.warn("Rejected endpoint URL '{}' because it has no host", endpointUrl);
+      return false;
+    }
+
+    try {
+      final InetAddress[] addresses = InetAddress.getAllByName(host);
+      for (InetAddress address : addresses) {
+        if (isBlockedAddress(address)) {
+          LOG.warn("Rejected endpoint URL '{}' because host '{}' resolves to a "
+              + "non-routable/internal address '{}'", endpointUrl, host, address.getHostAddress());
+          return false;
+        }
+      }
+    } catch (UnknownHostException e) {
+      LOG.warn("Rejected endpoint URL '{}' because host '{}' could not be resolved",
+          endpointUrl, host);
+      return false;
+    }
+
+    return true;
+  }
+
+  private static boolean isBlockedAddress(InetAddress address) {
+    return address.isAnyLocalAddress()
+        || address.isLoopbackAddress()
+        || address.isLinkLocalAddress()
+        || address.isSiteLocalAddress()
+        || address.isMulticastAddress();
+  }
+}
